const body = $input.item.json.body ?? $input.item.json;

const nome = (body.nome ?? body.name ?? '').toString().trim();
const whatsapp = (body.whatsapp ?? body.telefone ?? body.phone ?? '').toString().replace(/\D/g, '');
const source = body.source ?? 'curso-vip';
const createdAt = body.created_at ?? new Date().toISOString();

// Texto que a pessoa leu na tela
const profissao = body.profissao ?? '';
const habilitacao = body.habilitacao ?? '';
const momento = body.momento ?? '';

// Slug curto de cada resposta, usado nas tags
const profissaoCod = body.profissao_codigo ?? '';
const habilitacaoCod = body.habilitacao_codigo ?? '';
const momentoCod = body.momento_codigo ?? '';

const tags = [{ name: 'origem-' + source }];
if (profissaoCod) tags.push({ name: 'curso-vip-profissao-' + profissaoCod });
if (habilitacaoCod) tags.push({ name: 'curso-vip-habilitacao-' + habilitacaoCod });
if (momentoCod) tags.push({ name: 'curso-vip-momento-' + momentoCod });

const customFieldsValues = [];
if (whatsapp) {
  customFieldsValues.push({
    field_code: 'PHONE',
    values: [{ value: whatsapp, enum_code: 'WORK' }],
  });
}

// As respostas por extenso ficam na nota do lead: a equipe le direto no card,
// sem precisar decifrar as tags.
const nota = [
  'Curso VIP - respostas do formulario',
  '',
  '1. Profissao: ' + profissao,
  '2. Habilitacao profissional: ' + habilitacao,
  '3. Momento profissional: ' + momento,
  '',
  'WhatsApp: ' + whatsapp,
  'Enviado em: ' + createdAt,
].join('\n');

const payload = [
  {
    name: (nome ? nome + ' - Curso VIP' : 'Novo lead - Curso VIP'),
    _embedded: {
      tags,
      contacts: [
        {
          first_name: nome,
          custom_fields_values: customFieldsValues,
        },
      ],
    },
  },
];

return { json: { payload, nota, nome, whatsapp, profissao, habilitacao, momento, source, createdAt } };
